    /// fields are fullName.givenName, fullName.familyName, status, and externalId.
    ///
    /// When AIM is enabled and the user is an external identity (its external_id is
    /// set), only external_id can be updated; its other fields are sourced from your
    /// identity provider.
    ///
    /// `PATCH /api/2.0/identity/accounts/{account_id}/users/{user_id}`
    pub async fn update_user(&self, request: UpdateUserRequest) -> ::databricks_core::Result<User> {
        let path = format!(
            "/api/2.0/identity/accounts/{}/users/{}",
            path_param(self.api.account_id()?, false),
            path_param(&request.user_id.to_string(), false)
        );
        let mut call = Call::new(Method::PATCH, path);
        call = call.query(query::field("update_mask", &request.update_mask)?);
        call = call.json(&request.user)?;
        self.api.send::<User>(call).await
    }

